package dev.workshop.vaadin.talktracker.data;

import org.springframework.boot.CommandLineRunner;
import org.springframework.stereotype.Component;

@Component
public class DataInitializer implements CommandLineRunner {

    private final CategoryRepository categoryRepository;
    private final TalkRepository talkRepository;

    public DataInitializer(CategoryRepository categoryRepository, TalkRepository talkRepository) {
        this.categoryRepository = categoryRepository;
        this.talkRepository = talkRepository;
    }

    @Override
    public void run(String... args) {
        Category frontend = createCategory("Frontend");
        Category security = createCategory("Security");
        Category ai = createCategory("AI");
        Category cloud = createCategory("Cloud");
        Category modernization = createCategory("Modernization");
        Category architecture = createCategory("Architecture");
        Category testing = createCategory("Testing");
        Category data = createCategory("Data");
        Category devops = createCategory("DevOps");
        Category performance = createCategory("Performance");

        createTalk("Building Reactive UIs with Vaadin Flow",
                "This talk explores how Vaadin Flow enables developers to build modern, reactive user interfaces entirely in server-side Java. We will walk through the component model and demonstrate how data binding and event handling work without writing any JavaScript. Attendees will see live examples of complex forms, grids, and dashboards built with pure Java code. We also cover best practices for structuring large Vaadin applications into reusable components. The session includes a comparison of Vaadin Flow with traditional REST-plus-SPA approaches, highlighting trade-offs in developer productivity and runtime performance. Finally, we discuss how server push and reactive signals can bring real-time capabilities to your Vaadin apps. You will leave with a clear understanding of when Vaadin Flow is the right choice for your next project and how to get started quickly.",
                "Anna Müller", "English", frontend);
        createTalk("Zero Trust Architecture in Practice",
                "Zero trust is no longer a buzzword — it is a fundamental shift in how we think about network security. This talk covers the core principles of zero trust and how they apply to microservice environments running on Kubernetes. We walk through implementing mutual TLS between services, policy-based access control with Open Policy Agent, and identity-aware proxies. Real-world case studies illustrate common pitfalls teams encounter when transitioning from perimeter-based security. Attendees will learn how to design service meshes that enforce zero trust without sacrificing developer velocity. We also discuss observability strategies that help detect policy violations and lateral movement attempts in production. The session concludes with a practical checklist for teams beginning their zero trust journey.",
                "James O'Brien", "English", security);
        createTalk("Spring AI: From Prototype to Production",
                "Building a prototype with Spring AI is easy, but taking it to production requires careful planning. This talk covers the full journey from a local Ollama experiment to a scalable, monitored AI service running in the cloud. We discuss prompt engineering patterns, token management, and cost optimization strategies for OpenAI and other commercial providers. Attendees will learn how to implement fallback chains that switch between providers based on latency, cost, or availability. The session also covers structured output parsing, function calling, and how to integrate AI responses into existing Spring Boot workflows. We share lessons learned from running Spring AI in production for six months, including common failure modes and how to handle them gracefully. Practical code examples accompany every concept.",
                "Emily Watson", "English", ai);
        createTalk("JVM Performance Tuning for Spring Boot Applications",
                "Default JVM settings are rarely optimal for production workloads. This talk covers G1 and ZGC garbage collector tuning, heap sizing strategies, JIT compiler flags, and how to use JFR and async-profiler to identify bottlenecks. We walk through real production scenarios where small JVM configuration changes led to dramatic throughput improvements. Attendees will learn a systematic approach to performance analysis starting from GC logs through flame graphs to allocation profiling. The session also covers containerized JVM ergonomics including how the JVM detects CPU and memory limits in Kubernetes pods. We discuss common anti-patterns like over-provisioning heap memory and under-utilizing compiler optimizations. Each topic includes concrete before-and-after metrics from real applications to illustrate the impact.",
                "Ivan Petrov", "English", performance);
        createTalk("Kubernetes Operators in Java",
                "Kubernetes operators extend the platform with domain-specific automation, and Java developers can now build them without learning Go. This talk introduces the Java Operator SDK and walks through building a production-ready operator from scratch. We cover custom resource definitions, reconciliation loops, and status management with practical code examples. Attendees will learn how to handle edge cases like concurrent modifications, finalizers, and leader election in multi-replica deployments. The session demonstrates testing strategies including unit tests with mock Kubernetes APIs and integration tests with kind clusters. We also discuss when an operator is the right solution versus simpler alternatives like Helm charts or Kustomize overlays. Performance benchmarking results show how Java operators compare to Go-based alternatives in memory usage and reconciliation latency.",
                "David Park", "English", cloud);
        createTalk("CSS Container Queries for Responsive Layouts",
                "Las media queries han sido durante años la herramienta principal para el diseño responsivo, pero las container queries cambian las reglas del juego. En esta charla exploramos cómo las container queries permiten que los componentes se adapten al tamaño de su contenedor en lugar de al viewport. Veremos ejemplos prácticos de cómo refactorizar layouts existentes para aprovechar esta nueva capacidad. También analizamos la compatibilidad actual con los navegadores y las estrategias de fallback para entornos legacy. Los asistentes aprenderán a combinar container queries con CSS Grid y Flexbox para crear diseños verdaderamente modulares. Además, discutiremos cómo estas técnicas se integran con frameworks de componentes como Vaadin y Lit. La sesión incluye demostraciones en vivo y código reutilizable que los asistentes pueden aplicar directamente en sus proyectos.",
                "Sofia Reyes", "Spanish", frontend);
        createTalk("Hexagonal Architecture with Spring Boot",
                "Hexagonal architecture, also known as ports and adapters, is a powerful pattern for building applications that are easy to test and maintain over time. This talk explains the core concepts and demonstrates how to implement them cleanly in a Spring Boot application. We define clear boundaries between domain logic, application services, and infrastructure adapters using Java interfaces and dependency injection. Attendees will see how this architecture makes it trivial to swap database implementations, replace messaging systems, or add new delivery mechanisms like GraphQL alongside REST. The session includes a live coding exercise where we refactor a typical layered Spring Boot application into hexagonal architecture. We discuss common mistakes like leaking framework annotations into the domain layer. Testing becomes dramatically simpler because domain logic can be tested in isolation without Spring context.",
                "Michael Scott", "English", architecture);
        createTalk("Contract Testing with Spring Cloud Contract",
                "Integration tests are slow and brittle, and mocks can diverge from reality. Contract testing offers a middle ground that catches integration issues early without requiring a full environment. This session demonstrates Spring Cloud Contract for consumer-driven contract testing between microservices. We walk through defining contracts in Groovy DSL, generating stubs for consumers, and auto-generating tests for producers. Attendees will learn how to integrate contract testing into their CI/CD pipeline and how to manage contract evolution as APIs change over time. The talk also covers common pitfalls like overly strict contracts that break on harmless changes and overly loose contracts that miss real incompatibilities. We compare Spring Cloud Contract with Pact and discuss when each tool is the better choice for your team.",
                "Benjamin Clarke", "English", testing);
        createTalk("GitHub Actions for Java Projects: A Complete Guide",
                "GitHub Actions is the CI/CD platform of choice for many Java projects. This talk covers workflow design from simple build-and-test pipelines to complex multi-stage deployments. We demonstrate caching Maven and Gradle dependencies to cut build times by up to seventy percent. Attendees will learn how to set up matrix builds for multiple Java versions, configure secret management for deployment credentials, and trigger workflows on pull requests, tags, and schedules. The session covers reusable workflows and composite actions that reduce duplication across repositories. We also discuss self-hosted runners for builds that need special hardware or network access. Security considerations including OIDC-based authentication to cloud providers and artifact signing round out the talk. Real pipeline examples from open source projects illustrate each concept.",
                "Ryan Mitchell", "English", devops);
        createTalk("Spring Data JPA: Advanced Query Techniques",
                "Beyond basic CRUD operations, Spring Data JPA offers powerful query capabilities that many developers underutilize. This talk covers Specifications for dynamic queries, Projections for optimized data retrieval, and SpEL expressions for flexible repository methods. We demonstrate custom repository implementations that combine the convenience of Spring Data with the control of plain JPA or even native SQL. Attendees will learn how to avoid the infamous N+1 query problem using entity graphs, join fetches, and batch size tuning. The session also covers pagination best practices, auditing with Envers, and how to use Querydsl as an alternative to the Criteria API. We discuss the trade-offs between derived queries, JPQL, and native SQL and provide guidelines for choosing the right approach. Performance profiling with Hibernate statistics rounds out the session.",
                "Angela Davis", "English", data);
        createTalk("Migrating from Spring Boot 2 to 4",
                "Migrating a large application from Spring Boot 2 to 4 is a significant undertaking that touches nearly every layer of your codebase. This talk provides a practical, step-by-step migration guide based on real-world experience with multiple enterprise applications. We cover the transition from javax to jakarta namespaces, removed and deprecated APIs, and configuration property changes that break silently. Attendees will learn how to use OpenRewrite recipes to automate the most tedious parts of the migration. The session addresses common blockers like incompatible third-party libraries and how to find or create replacements. We also discuss testing strategies that give you confidence during the migration, including how to run tests against both versions simultaneously. A detailed timeline from a real migration project helps teams estimate effort and plan their own transition.",
                "Thomas Berg", "English", modernization);
        createTalk("Running LLMs Locally with Ollama",
                "No todas las organizaciones pueden enviar sus datos a APIs externas, lo que convierte a la ejecución local de LLMs en una necesidad práctica. Esta charla es una guía práctica para ejecutar y ajustar modelos de lenguaje en tu propio hardware usando Ollama. Exploraremos la instalación, configuración y los requisitos de hardware para diferentes tamaños de modelo, desde 7B hasta 70B parámetros. Los asistentes verán demostraciones en vivo de inferencia local con tiempos de respuesta sorprendentemente rápidos en hardware de consumo. También cubrimos técnicas de cuantización que reducen los requisitos de memoria sin sacrificar demasiada calidad. Discutiremos cómo integrar Ollama con Spring AI para crear aplicaciones Java que funcionan completamente offline. Finalmente, comparamos el rendimiento y la calidad de varios modelos abiertos como Llama, Mistral y Gemma para diferentes casos de uso empresariales.",
                "Alejandro Torres", "Spanish", ai);
        createTalk("Optimizing Hibernate Performance: Beyond the Basics",
                "Hibernate-Performance-Probleme sind in fast jedem Spring-Boot-Projekt zu finden. Dieser Vortrag geht über die üblichen Tipps hinaus und behandelt fortgeschrittene Themen wie Batch-Fetching-Strategien, Read-Only-Transaktionen für Lesezugriffe und Second-Level-Caching mit Caffeine oder Redis. Wir zeigen, wie man N+1 Queries in Produktion erkennt und behebt, ohne den gesamten Code umzuschreiben. Die Teilnehmer lernen den Einsatz von Hibernate Statistics und JPA-Metamodell für typsichere Queries. Außerdem besprechen wir die Unterschiede zwischen Eager und Lazy Loading und wann welche Strategie sinnvoll ist. Der Vortrag enthält Live-Demos mit dem Hibernate SQL-Logger und Erklärungen zu Execution Plans. Abschließend vergleichen wir die Performance von JPQL, Criteria API und nativen Queries anhand konkreter Benchmarks aus einem Produktivsystem.",
                "Andreas Huber", "German", performance);
        createTalk("OAuth 2.1 and Spring Security 7",
                "OAuth 2.1 consolidates years of security best practices into a streamlined specification, and Spring Security 7 provides first-class support for it. This session explains the key changes from OAuth 2.0, including the removal of the implicit grant, mandatory PKCE for public clients, and stricter redirect URI matching. We demonstrate how to configure Spring Security 7 for both authorization servers and resource servers using the new APIs. Attendees will see practical examples of token exchange, refresh token rotation, and scope-based access control. The talk also covers integration with external identity providers like Keycloak and Okta. We conclude with a security checklist for production deployments that teams can adopt immediately. Each configuration option is explained with its security rationale so attendees understand not just how but why.",
                "Priya Sharma", "English", security);
        createTalk("Event-Driven Systems with Kafka and Spring",
                "Event-driven architectures enable loosely coupled systems that scale independently and recover gracefully from failures. This talk provides a comprehensive guide to designing and implementing event-driven systems using Apache Kafka and Spring Cloud Stream. We cover event modeling, topic design, and partitioning strategies that ensure ordered processing where it matters. Attendees will learn about the different messaging patterns — event notification, event-carried state transfer, and event sourcing — and when to use each one. The session demonstrates how to implement the outbox pattern to ensure reliable event publishing alongside database transactions. We also address operational concerns like schema evolution with Avro and the Schema Registry, consumer group management, and dead letter queues for handling poison messages. Performance tuning tips from production experience round out the session.",
                "Olivia Johnson", "English", architecture);
        createTalk("Web Components in 2026",
                "Web Components have matured significantly over the past years, and 2026 marks a turning point for enterprise adoption. This session provides a comprehensive overview of the current ecosystem, including Shadow DOM, Custom Elements, and HTML Templates. We examine how major frameworks like Vaadin, Angular, and React interact with Web Components and where interoperability shines or breaks down. Practical examples show how to wrap third-party Web Components for use in Java-based server-side frameworks. Attendees will learn strategies for building a shared component library that works across teams using different frontend stacks. We also cover testing strategies, accessibility considerations, and performance profiling for Web Component-heavy applications. The session concludes with a look at emerging standards like Declarative Shadow DOM and CSS Parts that further improve the developer experience.",
                "Liam Chen", "English", frontend);
        createTalk("Dockerizing Spring Boot: Best Practices",
                "Creating Docker images for Spring Boot apps is easy, but creating good ones takes knowledge. This session covers multi-stage builds that separate build and runtime environments, JVM memory configuration for containers including heap and non-heap tuning, and health check endpoints that integrate with orchestrator probes. We discuss security hardening practices like running as a non-root user, using distroless or slim base images, and scanning for vulnerabilities with Trivy. Attendees will learn about Spring Boot's layered jar format and how it dramatically improves image rebuild times by leveraging Docker layer caching. The talk also covers .dockerignore best practices, build arguments for environment-specific configuration, and how to use BuildKit features for faster builds. We compare Dockerfile-based builds with Cloud-Native Buildpacks and discuss when each approach makes more sense.",
                "Maria Santos", "English", devops);
        createTalk("Serverless Java with GraalVM Native Image",
                "Cold start times have long been Java's Achilles heel in serverless environments, but GraalVM Native Image changes everything. This session shows how to achieve sub-100ms cold starts for Java functions running on AWS Lambda, Azure Functions, and Google Cloud Functions. We walk through the native image compilation process, common pitfalls with reflection and dynamic proxies, and how Spring Boot 4 simplifies native builds with ahead-of-time processing. Attendees will see benchmarks comparing JVM versus native performance across different workload types. The talk covers strategies for managing native image build times in CI/CD pipelines and how to debug issues that only appear in native mode. We also discuss the trade-offs between native images and CRaC-based approaches for reducing startup time while keeping the JVM runtime optimizations that benefit long-running applications.",
                "Nina Petrov", "English", cloud);
        createTalk("Event Streaming with Apache Kafka and Spring Boot",
                "Kafka ist mehr als ein Message Broker — es ist eine vollwertige Streaming-Plattform. Dieser Vortrag zeigt, wie man mit Spring Boot und Kafka Streams Echtzeit-Datenpipelines aufbaut, einschließlich Windowing, State Stores und interaktive Queries. Wir behandeln die Grundlagen der Stream-Processing-Topologie und demonstrieren, wie man komplexe Aggregationen und Joins über mehrere Topics implementiert. Die Teilnehmer lernen, wie man Kafka Connect für die Integration mit externen Systemen wie Datenbanken und Elasticsearch konfiguriert. Außerdem besprechen wir Fehlerbehandlung, Dead-Letter-Topics und Schema-Evolution mit dem Confluent Schema Registry. Der Vortrag enthält Performance-Benchmarks und zeigt, wie man den Durchsatz durch Partitionierung und Consumer-Group-Konfiguration optimiert. Praxisbeispiele aus einem Produktivsystem veranschaulichen jeden Konzeptschritt.",
                "Tobias Müller", "German", data);
        createTalk("Property-Based Testing in Java with jqwik",
                "Example-based tests only cover cases you think of, which means edge cases often slip through. Property-based testing generates thousands of random inputs to find failures you would never write manually. This talk introduces jqwik, the leading property-based testing framework for Java, and shows how to apply it to real-world code. We cover defining properties, creating custom arbitraries for domain objects, and combining properties for comprehensive coverage. Attendees will see practical examples including testing serialization roundtrips, mathematical invariants, and state machine models. The session also covers shrinking — how jqwik automatically simplifies failing inputs to minimal counterexamples that are easy to debug. We discuss integration with JUnit 5 and how to gradually adopt property-based testing alongside existing example-based test suites without disrupting your workflow.",
                "Luisa Martínez", "English", testing);
        createTalk("Strangler Fig Pattern for Legacy Modernization",
                "Rewriting a legacy system from scratch is risky and often fails, but the Strangler Fig pattern offers a proven alternative. This talk explains how to incrementally replace a monolith by routing requests through a facade that gradually shifts traffic to new services. We demonstrate practical implementation using Spring Cloud Gateway as the routing layer between legacy and modern components. Attendees will see how to identify the right starting points for strangulation based on business value and technical risk. The session covers data synchronization challenges when old and new systems need to share state during the transition period. We discuss organizational strategies for running dual systems, including how to maintain team morale during what can be a multi-year effort. Real project metrics show how one team reduced their legacy codebase by seventy percent over eighteen months while maintaining zero downtime.",
                "Rachel Adams", "English", modernization);
        createTalk("RAG Patterns for Enterprise Search",
                "Retrieval-Augmented Generation combines the power of large language models with your organization's proprietary data. This talk presents battle-tested patterns for implementing RAG systems that actually work at enterprise scale. We cover document ingestion pipelines, chunking strategies, and vector database selection including pgvector, Weaviate, and Milvus. Attendees will learn how to evaluate retrieval quality using precision, recall, and NDCG metrics. The session demonstrates how to build a complete RAG pipeline using Spring AI with a real-world document corpus. We also address critical concerns like hallucination detection, source attribution, and access control for sensitive documents. Advanced topics include hybrid search combining keyword and semantic retrieval, re-ranking strategies that dramatically improve answer quality, and techniques for handling multi-language document collections.",
                "Marco Rossi", "English", ai);
        createTalk("Reactive Programming with Spring WebFlux: When and Why",
                "Reactive programming is not always the answer, but when it is, the benefits are dramatic. This talk clarifies when WebFlux outperforms traditional Spring MVC and demonstrates practical patterns for building reactive APIs and streaming endpoints. We cover the fundamentals of Project Reactor including Mono, Flux, operators, and backpressure handling. Attendees will see side-by-side comparisons of blocking versus reactive implementations for common use cases like API gateways, server-sent events, and database streaming. The session also addresses the testing challenge with StepVerifier and how to debug reactive chains that produce cryptic stack traces. We discuss the learning curve honestly and present strategies for teams adopting reactive programming gradually. Performance benchmarks from real applications demonstrate where reactive shines and where the added complexity is not justified.",
                "Natalie Chen", "English", performance);
        createTalk("Supply Chain Security for Java Projects",
                "Los ataques a la cadena de suministro de software se han convertido en una de las amenazas más críticas para los proyectos Java. Esta charla analiza vectores de ataque reales, desde la inyección de dependencias maliciosas hasta la manipulación de artefactos en repositorios Maven. Exploraremos herramientas como Sigstore, SLSA y Dependabot para proteger el pipeline de build. Los asistentes aprenderán a configurar verificación de firmas en Maven y Gradle, y cómo implementar SBOMs para tener visibilidad completa de las dependencias. También discutiremos estrategias organizativas como el uso de repositorios proxy y políticas de actualización de dependencias. Casos de estudio de incidentes reales ilustran por qué cada equipo debe tomar la seguridad de la cadena de suministro en serio. Finalmente presentamos un framework de evaluación de riesgo para priorizar las medidas de protección más efectivas.",
                "Carlos Mendoza", "Spanish", security);
        createTalk("Modular Monoliths: The Best of Both Worlds",
                "Microservices have become the default architectural choice, but they introduce significant operational complexity that many teams are not prepared for. This talk makes the case for modular monoliths as a pragmatic alternative that delivers most of the benefits of microservices without the distributed systems headaches. We demonstrate how to structure a Spring Boot application into well-defined modules with explicit boundaries and minimal coupling. Attendees will learn how to enforce module boundaries using ArchUnit tests and Java module system features. The session covers strategies for shared data access, including when modules should share a database and when they need their own schemas. We discuss how a well-structured monolith can be selectively decomposed into services later if and when the need actually arises. Real-world examples from teams that migrated from microservices back to a modular monolith illustrate the approach.",
                "Henrik Larsson", "English", architecture);
        createTalk("Accessible Web Applications from Day One",
                "Accessibility is not an afterthought — it is a fundamental quality attribute that affects millions of users. This session covers WCAG 2.2 compliance in modern Java web frameworks, focusing on ARIA roles, keyboard navigation, and screen reader compatibility in Vaadin and React applications. We demonstrate common accessibility failures and how to fix them, including form labeling, focus management, color contrast, and dynamic content updates. Attendees will learn how to integrate automated accessibility testing with axe-core into their CI/CD pipeline and how to conduct manual testing with screen readers like NVDA and VoiceOver. The talk also covers legal requirements in the EU and US that make accessibility mandatory for many applications. We provide a prioritized checklist that teams can use to improve accessibility incrementally without blocking feature development.",
                "Emma Johansson", "English", frontend);
        createTalk("Multi-Cloud Strategies That Actually Work",
                "La estrategia multi-cloud suena atractiva en las presentaciones ejecutivas, pero la realidad de operar cargas de trabajo en múltiples proveedores es mucho más compleja. Esta charla comparte lecciones aprendidas de equipos que ejecutan servicios de producción en AWS, Azure y GCP simultáneamente. Analizamos los patrones que funcionan, como el uso de Kubernetes como capa de abstracción y Terraform para infraestructura declarativa. También discutimos los antipatrones más comunes, incluyendo intentar usar el mínimo común denominador de cada proveedor. Los asistentes aprenderán estrategias prácticas para gestionar redes, identidades y observabilidad en un entorno multi-cloud. Cubrimos los costos ocultos que los equipos suelen descubrir demasiado tarde, como el tráfico de egress y las diferencias en modelos de facturación. Finalmente, presentamos un framework de decisión para evaluar cuándo multi-cloud realmente aporta valor.",
                "Lucas Fernández", "Spanish", cloud);
        createTalk("Testcontainers: Integration Testing with Real Dependencies",
                "Testcontainers revolutioniert Integrationstests, indem es echte Datenbanken, Message Broker und andere Infrastruktur in Docker-Containern für Tests bereitstellt. Dieser Vortrag zeigt Best Practices für schnelle und zuverlässige Container-basierte Tests in Spring Boot. Wir behandeln die Konfiguration von PostgreSQL, Redis und Kafka als Testcontainer und zeigen, wie man die Startzeit durch Wiederverwendung von Containern zwischen Tests minimiert. Die Teilnehmer lernen, wie man Testcontainers mit dem Spring-Boot-Test-Framework und Slices wie DataJpaTest kombiniert. Außerdem besprechen wir die Integration in CI/CD-Pipelines einschließlich Docker-in-Docker-Konfiguration und Ressourcenlimits. Der Vortrag enthält Tipps zur Fehlersuche bei Container-Startproblemen und zeigt, wie man eigene Container-Images für spezialisierte Testszenarien erstellt. Abschließend vergleichen wir Testcontainers mit eingebetteten Alternativen wie H2.",
                "Markus Schäfer", "German", testing);
        createTalk("Platform Engineering: Building an Internal Developer Platform",
                "Platform Engineering geht über DevOps hinaus und stellt internen Entwicklerteams eine Self-Service-Plattform bereit, die Produktivität und Konsistenz steigert. Dieser Vortrag zeigt, wie man mit Backstage als Entwicklerportal, Crossplane für Infrastructure-as-Code und ArgoCD für GitOps-basierte Deployments eine interne Entwicklerplattform aufbaut. Wir besprechen die wichtigsten Bausteine einer guten Plattform: Service-Katalog, Template-basierte Projekterstellung, automatisierte Umgebungsprovisionierung und integrierte Observability. Die Teilnehmer erfahren, wie man die Balance zwischen Standardisierung und Flexibilität findet, damit Teams produktiv arbeiten können, ohne die Plattform zu umgehen. Außerdem diskutieren wir Organisationsmodelle für Platform-Teams und wie man den Erfolg einer Plattform durch Developer-Experience-Metriken misst. Praxisberichte aus drei Unternehmen unterschiedlicher Größe runden den Vortrag ab.",
                "Thomas Richter", "German", devops);
        createTalk("Migrating from Oracle to PostgreSQL",
                "Oracle license costs drive many organizations to PostgreSQL, but migration is not trivial. This session covers the complete migration journey from assessment through execution to validation. We discuss PL/SQL to PL/pgSQL conversion including stored procedures, triggers, and packages. Data type mapping covers subtle differences in number handling, date types, and LOB storage. Attendees will learn how to handle Oracle-specific features like sequences, synonyms, and materialized views in PostgreSQL. The talk covers schema migration tools like ora2pg and AWS Schema Conversion Tool with honest assessments of their capabilities and limitations. We also discuss performance tuning specific to PostgreSQL including vacuum configuration, connection pooling with PgBouncer, and index strategies that differ from Oracle. A migration timeline template helps teams plan and track progress through each phase.",
                "Deepak Krishnan", "English", data);
        createTalk("AI-Assisted Code Review",
                "Code reviews are essential but time-consuming, and AI tools can help without replacing the human reviewer. This talk explores practical ways to integrate AI into your code review workflow using both commercial APIs and local models. We demonstrate automated detection of common issues like security vulnerabilities, performance anti-patterns, and style inconsistencies. Attendees will see how to build custom review bots that understand your team's specific conventions and architecture decisions. The session covers prompt engineering techniques that produce actionable review comments rather than vague suggestions. We also discuss the psychology of AI-assisted reviews and how to maintain team trust when machines are involved in quality gates. Real metrics from teams that adopted AI-assisted reviews show measurable improvements in defect detection rates and review turnaround times while reducing reviewer fatigue.",
                "Sarah Kim", "English", ai);
        createTalk("From Java 11 to 21: Features You Should Adopt Now",
                "Java has evolved dramatically since version 11, and many teams are not yet leveraging the most impactful features available in Java 21. This talk cuts through the noise and identifies which features deliver the most value for typical enterprise applications. We start with virtual threads and demonstrate how they simplify concurrent programming while dramatically improving throughput for I/O-bound workloads. Pattern matching with sealed types enables more expressive and safer code, and we show refactoring examples from real codebases. Records and compact constructors reduce boilerplate in data transfer objects and domain models. The session also covers text blocks, switch expressions, and the new SequencedCollection interfaces that make everyday coding more pleasant. We conclude with features you should skip or defer, explaining why not every shiny new addition belongs in production code right away.",
                "Kenji Tanaka", "English", modernization);
        createTalk("Securing WebSocket Connections in Spring Boot",
                "WebSockets open persistent connections that require careful security handling beyond traditional HTTP request-response patterns. This talk covers authentication during the WebSocket handshake, including how to validate tokens and establish session identity. We demonstrate message-level authorization that controls which users can send and receive on specific channels. Rate limiting strategies prevent abuse without degrading the experience for legitimate users. Attendees will learn how to prevent common WebSocket vulnerabilities like cross-site WebSocket hijacking and denial-of-service through message flooding. The session shows how to configure Spring Security for WebSocket endpoints including STOMP-based messaging with Spring's message broker. We also cover TLS configuration, origin checking, and how to implement heartbeat mechanisms that detect stale connections. Practical examples use a real-time collaboration application as the running demo.",
                "Fatima Al-Hassan", "English", security);
        createTalk("Database Query Optimization for Java Developers",
                "Slow queries are the most common performance bottleneck in enterprise applications, yet many Java developers struggle to diagnose them. This session teaches developers how to read execution plans in PostgreSQL and MySQL, understanding sequential scans, index scans, hash joins, and sort operations. We cover creating effective indexes including composite indexes, partial indexes, and covering indexes that eliminate table lookups. Common anti-patterns like implicit type casting, functions on indexed columns, and OR conditions that prevent index usage are explained with fixes. Attendees will learn how to use tools like pg_stat_statements, slow query logs, and EXPLAIN ANALYZE to find problematic queries in production. The talk also covers connection pool monitoring, query result caching strategies, and when to denormalize data for read performance. Every optimization technique is demonstrated with before-and-after benchmarks.",
                "Omar Farouk", "English", performance);
        createTalk("Micro Frontends with Module Federation",
                "Micro frontends extend the microservice philosophy to the browser, enabling independent teams to develop and deploy frontend modules autonomously. This talk demonstrates how Webpack Module Federation enables these modules to compose seamlessly at runtime without build-time coordination. We walk through setting up a host application that dynamically loads remote modules, including shared dependency management that prevents duplicate framework loading. Attendees will learn routing strategies that maintain a seamless user experience across independently deployed modules. The session covers versioning, backward compatibility, and how to handle breaking changes without coordinated deployments. We also discuss the organizational implications of micro frontends and when the added infrastructure complexity is justified. Performance considerations including lazy loading, caching strategies, and initial load optimization ensure your micro frontend architecture does not degrade the user experience.",
                "Tom Williams", "English", frontend);
        createTalk("Domain-Driven Design in Practice with Spring Boot",
                "DDD-Konzepte wie Bounded Contexts, Aggregates und Value Objects klingen in der Theorie überzeugend, scheitern aber oft an der praktischen Umsetzung in realen Projekten. Dieser Vortrag zeigt anhand eines konkreten Beispiels, wie man DDD in einer Spring-Boot-Anwendung erfolgreich implementiert. Wir beginnen mit der strategischen Modellierung durch Event Storming und leiten daraus Bounded Contexts ab. Anschließend implementieren wir taktische Muster wie Aggregates mit Invarianten, Value Objects als Records und Domain Events für die lose Kopplung zwischen Kontexten. Die Teilnehmer lernen, wie man Repositories als Ports im Sinne der Hexagonalen Architektur gestaltet und wie Spring Data JPA als Adapter fungiert. Wir diskutieren häufige Fehler wie anämische Domänenmodelle und zu große Aggregates. Der Vortrag schließt mit Tipps zur Team-Organisation entlang von Bounded Contexts.",
                "Wolfgang Meier", "German", architecture);
        createTalk("Spring Boot on Azure Container Apps",
                "Azure Container Apps provide a managed serverless container environment perfect for Spring Boot microservices that need to scale dynamically without managing Kubernetes clusters. This session covers deployment strategies including blue-green and canary releases using revision management. We demonstrate autoscaling configuration based on HTTP traffic, queue length, and custom metrics from your application. Attendees will learn how to integrate with Azure services like Cosmos DB for NoSQL storage, Service Bus for messaging, and Key Vault for secrets management. The talk covers Dapr integration for service-to-service communication, pub/sub messaging, and distributed state management. We also discuss networking options including VNet integration, custom domains, and ingress configuration. Monitoring with Application Insights and Log Analytics provides end-to-end observability. Cost comparison with AKS and other Azure compute options helps teams make informed decisions.",
                "Sandra Mitchell", "English", cloud);
        createTalk("Monitoring Spring Boot with Prometheus and Grafana",
                "Effective monitoring catches issues before users notice them and provides the data needed for informed capacity planning. This talk walks through setting up comprehensive monitoring for Spring Boot applications using Micrometer, Prometheus, and Grafana. We cover built-in metrics including JVM statistics, HTTP request rates, and database connection pool health. Attendees will learn how to create custom business metrics using counters, gauges, timers, and distribution summaries. The session demonstrates building Grafana dashboards that provide meaningful visibility into application health and performance trends. We also cover alerting rules in Prometheus that notify teams about anomalies before they become outages. Advanced topics include exemplars that link metrics to distributed traces, histogram quantile calculations for SLA monitoring, and federation strategies for multi-cluster environments. Each configuration is shown with copy-paste-ready examples.",
                "Lucy Wang", "English", devops);
        createTalk("Time-Series Data with TimescaleDB and Spring Boot",
                "IoT, monitoring, and financial applications generate massive volumes of time-series data that traditional relational databases handle poorly. This talk shows how to use TimescaleDB as a PostgreSQL extension for efficient time-series storage, querying, and aggregation in Spring Boot applications. We cover hypertable creation, chunk management, and compression policies that reduce storage requirements by up to ninety percent. Attendees will learn how to write efficient time-range queries, continuous aggregates for pre-computed rollups, and data retention policies that automatically expire old data. The session demonstrates integration with Spring Data JPA including custom repository methods for time-series-specific operations. We also cover real-time alerting using TimescaleDB's continuous aggregates combined with PostgreSQL NOTIFY. Performance benchmarks compare TimescaleDB with InfluxDB and plain PostgreSQL for typical time-series workloads encountered in enterprise applications.",
                "Ingrid Olsen", "English", data);
        createTalk("Building AI Agents with Spring AI and Tool Calling",
                "AI agents that can take actions are the next evolution beyond simple chat interfaces. This session demonstrates how to build autonomous agents using Spring AI's function calling capabilities, including multi-step reasoning and tool orchestration. We walk through defining Java methods as tools that the LLM can invoke, handling parameter validation, and managing tool execution results. Attendees will see how to build agents that can query databases, call REST APIs, send notifications, and make decisions based on intermediate results. The session covers safety patterns including human-in-the-loop confirmation for high-impact actions, rate limiting, and audit logging. We discuss prompt engineering techniques that improve tool selection accuracy and reduce hallucinated tool calls. Advanced topics include multi-agent orchestration where specialized agents collaborate on complex tasks and memory systems that maintain context across conversations.",
                "Daniel Fischer", "English", ai);
        createTalk("Mutation Testing: Finding Gaps in Your Test Suite",
                "Code coverage can give a false sense of security because it only measures which lines execute, not whether the tests actually verify correct behavior. Mutation testing measures the real effectiveness of your tests by introducing small changes called mutants to the code and checking if tests catch them. This session demonstrates PIT, the most popular mutation testing tool for Java projects. We walk through configuring PIT with Maven and Gradle, interpreting mutation scores, and understanding which mutant types matter most. Attendees will learn how to focus mutation testing on critical business logic where undetected mutations pose the greatest risk. The session covers strategies for dealing with equivalent mutants and how to keep mutation testing fast enough for regular CI runs. We also discuss how mutation testing complements other quality techniques like code review and static analysis to build a comprehensive quality strategy.",
                "Amy Foster", "English", testing);
        createTalk("Modernizing Database Access with jOOQ",
                "Muchos proyectos Java todavía utilizan JDBC plano o ORMs desactualizados que generan consultas ineficientes y dificultan el mantenimiento. Esta charla presenta jOOQ como una alternativa moderna que combina SQL tipado con la potencia del generador de código. Exploraremos cómo jOOQ genera clases a partir del esquema de base de datos, proporcionando autocompletado y verificación en tiempo de compilación para todas las consultas. Los asistentes verán cómo migrar gradualmente desde JPA o JDBC hacia jOOQ sin necesidad de reescribir todo de una vez. Cubrimos patrones avanzados como consultas dinámicas, funciones de ventana y CTEs recursivos que son difíciles de expresar con ORMs tradicionales. También discutimos la integración con Spring Boot y cómo configurar la generación de código en el pipeline de CI/CD. Finalmente, presentamos benchmarks que comparan el rendimiento de jOOQ con Hibernate en escenarios de lectura intensiva.",
                "Isabel García", "Spanish", modernization);
        createTalk("Server-Side Rendering vs. Client-Side Rendering in 2026",
                "Die Debatte zwischen SSR und CSR hat sich weiterentwickelt und bietet heute deutlich mehr Nuancen als das simple Entweder-Oder früherer Jahre. Dieser Vortrag analysiert die aktuellen Rendering-Strategien einschließlich Streaming SSR, Islands Architecture, Partial Hydration und Resumability. Wir vergleichen die Performance-Charakteristiken jeder Strategie anhand konkreter Metriken wie Time to First Byte, Largest Contentful Paint und Time to Interactive. Die Teilnehmer lernen, welche Strategie für welchen Anwendungsfall am besten geeignet ist — von content-lastigen Websites über interaktive Dashboards bis hin zu datenintensiven Unternehmensanwendungen. Außerdem diskutieren wir, wie Server-Side-Frameworks wie Vaadin und Next.js diese Strategien implementieren und welche Trade-offs sie dabei eingehen. Der Vortrag enthält praktische Entscheidungshilfen und Architektur-Templates für die häufigsten Szenarien.",
                "Maximilian Weber", "German", frontend);
        createTalk("Memory-Efficient Java: Reducing Heap Consumption",
                "Los problemas de memoria son comunes en aplicaciones Java empresariales y pueden causar desde degradación de rendimiento hasta caídas completas del servicio. Esta charla cubre técnicas probadas para reducir el consumo de heap en aplicaciones Java. Comenzamos con compact strings y cómo la JVM optimiza automáticamente el almacenamiento de cadenas. Exploramos el uso de off-heap storage con ByteBuffers y memoria directa para grandes conjuntos de datos. Los asistentes aprenderán sobre object pooling, interning de strings y cómo elegir las estructuras de datos correctas para minimizar el overhead de memoria. También mostramos cómo identificar memory leaks usando herramientas como Eclipse MAT, VisualVM y Java Flight Recorder. Discutimos las diferencias entre soft references, weak references y phantom references y cuándo usar cada una. Finalmente, presentamos técnicas de profiling que revelan dónde se concentra el consumo de memoria.",
                "Ricardo Peña", "Spanish", performance);
        createTalk("Secrets Management with HashiCorp Vault and Spring",
                "Hard-coded secrets are still one of the most common security mistakes in Java applications, leading to credential exposure in version control and container images. This session demonstrates how to integrate HashiCorp Vault with Spring Boot for comprehensive secrets management. We cover dynamic database credentials that are automatically rotated, eliminating long-lived passwords. Attendees will learn how to use Vault's transit engine for encryption-as-a-service without managing cryptographic keys directly. The talk covers authentication methods including Kubernetes service account tokens, AppRole for CI/CD pipelines, and cloud IAM integration. We demonstrate Spring Cloud Vault's configuration property source that makes Vault secrets available through standard Spring property resolution. Advanced topics include secret versioning, policy management with HCL, and audit logging that provides a complete trail of who accessed which secrets. A disaster recovery strategy ensures secrets remain available during Vault outages.",
                "Viktor Kozlov", "English", security);
        createTalk("CQRS and Event Sourcing with Axon Framework",
                "CQRS separates read and write models for better scalability, and event sourcing provides a complete audit trail of every state change. This session demonstrates implementing both patterns with Axon Framework and Spring Boot, providing a practical foundation for building complex business applications. We cover aggregate design, command handling, and event publication with detailed code examples. Attendees will learn about saga orchestration for coordinating multi-step business processes that span multiple aggregates. The session demonstrates projection building for read-optimized query models and how to rebuild projections from the event store when requirements change. We discuss operational concerns including event store sizing, snapshot strategies for aggregates with long event histories, and dead letter queue handling. Performance considerations cover concurrent command processing, event batching, and read model indexing strategies. A comparison with simpler alternatives helps teams decide whether CQRS and event sourcing are the right fit.",
                "Christina Papadopoulos", "English", architecture);
        createTalk("GitOps with ArgoCD and Spring Boot",
                "GitOps makes your Git repository the single source of truth for both infrastructure and application state, providing auditable, reproducible deployments. This talk demonstrates how to set up a complete GitOps pipeline for Spring Boot applications using ArgoCD. We cover repository structure for multi-environment deployments, Kustomize overlays for environment-specific configuration, and Helm chart management for complex applications. Attendees will learn how to implement progressive delivery with canary and blue-green deployment strategies using ArgoCD Rollouts. The session covers environment promotion workflows that move changes from development through staging to production with automated validation gates. We discuss secrets management in GitOps including sealed secrets and external secrets operator integration. Rollback procedures and disaster recovery strategies ensure teams can quickly recover from failed deployments. Monitoring ArgoCD itself with Prometheus metrics rounds out the operational perspective.",
                "Erik Svensson", "English", cloud);
        createTalk("GraphQL with Spring for GraphQL",
                "Spring for GraphQL provides a first-class GraphQL experience for Spring developers, combining the flexibility of GraphQL with the power of the Spring ecosystem. This session covers schema-first development where you define the GraphQL schema and Spring maps it to data fetchers automatically. We demonstrate efficient data loading with DataLoader that eliminates the N+1 problem common in naive GraphQL implementations. Attendees will learn how to implement subscriptions for real-time updates using WebSocket and SSE transports. The talk covers security integration including field-level authorization, input validation, and query complexity analysis that prevents denial-of-service through deeply nested queries. We also discuss pagination with the Relay cursor specification, error handling best practices, and file upload support. Performance monitoring with GraphQL-specific metrics and tracing helps teams optimize their API in production. A comparison with REST helps teams decide when GraphQL is worth the added complexity.",
                "Paul Whitfield", "English", data);
        createTalk("End-to-End Testing for Vaadin Applications",
                "Vaadin applications require specific testing strategies due to their server-side rendering model and client-server communication patterns. This talk covers Vaadin TestBench for browser-based testing with element-specific selectors that survive DOM changes. We demonstrate Playwright integration as a framework-agnostic alternative that works well for Vaadin applications with proper waiting strategies. Attendees will learn best practices for writing reliable end-to-end tests including custom wait conditions for server roundtrips, handling lazy-loaded grids, and testing dialog interactions. The session covers page object patterns that create maintainable test code and reduce duplication across test suites. We also discuss visual regression testing that catches unintended style changes using screenshot comparison tools. CI/CD integration including parallel test execution, headless browser configuration, and flaky test detection strategies ensure your test suite remains reliable and fast. Real examples from a production Vaadin application demonstrate every technique.",
                "Johan Eriksson", "English", testing);
        createTalk("Feature Flags with Spring Boot and OpenFeature",
                "Feature flags decouple deployment from release, enabling teams to deploy code to production without exposing incomplete features to users. This session demonstrates how to implement feature flags in Spring Boot using the OpenFeature standard, which provides a vendor-neutral API that works across different feature flag providers. We cover progressive rollouts that gradually increase the percentage of users seeing a new feature while monitoring error rates and performance. Attendees will learn how to implement A/B testing with feature flags to make data-driven product decisions. The talk covers flag lifecycle management including creating, evaluating, and retiring flags to prevent technical debt from accumulating. We demonstrate integration with popular providers like LaunchDarkly, Flagsmith, and open-source alternatives. Context-based targeting allows different flag values based on user attributes, geography, or subscription tier. Testing strategies ensure your application behaves correctly under all flag combinations.",
                "Kevin O'Malley", "English", devops);
        createTalk("Design Systems with Lit and Web Components",
                "Building a design system that works across frameworks requires technology-agnostic components, and Lit provides a lightweight, standards-based approach to creating them. This talk shows how to build a design system with Lit that integrates seamlessly with React, Angular, Vue, and Vaadin applications. We cover component architecture including styling with CSS custom properties, shadow DOM encapsulation, and slot-based composition patterns. Attendees will learn how to create a comprehensive component library including buttons, inputs, cards, dialogs, and navigation elements with consistent theming support. The session demonstrates documentation generation with Storybook for Web Components and automated visual regression testing. We discuss versioning strategies, backward compatibility policies, and how to roll out design system updates across consuming applications. Accessibility is treated as a first-class concern with ARIA attribute management and keyboard navigation patterns built into every component from the start.",
                "Aisha Patel", "English", frontend);
        createTalk("Fine-Tuning Open Models for Domain-Specific Tasks",
                "General-purpose LLMs often fall short on specialized tasks like medical text classification, legal document analysis, or domain-specific code generation. This talk shows how to fine-tune open models like Llama and Mistral for domain-specific applications using parameter-efficient techniques. We cover LoRA and QLoRA adapters that enable fine-tuning on consumer hardware by training only a small fraction of the model's parameters. Attendees will learn the complete fine-tuning pipeline from dataset preparation and formatting through training configuration to evaluation and deployment. The session demonstrates how to evaluate model quality using both automated metrics like BLEU and ROUGE and human evaluation protocols. We discuss when fine-tuning is the right approach versus RAG or prompt engineering and how to combine these techniques for optimal results. Deployment strategies cover serving fine-tuned models with vLLM and integrating them with Spring AI for production Java applications.",
                "Li Wei", "English", ai);
        createTalk("Automated Refactoring with OpenRewrite",
                "OpenRewrite enables large-scale, automated code refactoring across entire codebases with semantic understanding of the code structure. This session shows how to use existing recipes for common tasks like framework migrations, code style enforcement, and security vulnerability patching. We walk through the recipe catalog covering Spring Boot migration recipes, JUnit 4 to 5 migration, and Java version upgrade recipes that handle API changes automatically. Attendees will learn how to write custom recipes using the Lossless Semantic Tree model that preserves formatting and comments during transformations. The session covers testing recipes with rewrite-test to ensure they transform code correctly across edge cases. We demonstrate running recipes across multi-module Maven and Gradle projects and how to review changes before committing. Advanced topics include composing recipes for multi-step migrations and contributing recipes back to the open-source community. Adoption strategies help teams build confidence in automated refactoring by starting with low-risk transformations.",
                "Brian Foster", "English", modernization);
        createTalk("HTTP/3 and QUIC: Impact on Java Web Applications",
                "HTTP/3 with QUIC eliminates head-of-line blocking and reduces connection setup latency by combining transport and cryptographic handshakes into a single round trip. This talk explores the current state of HTTP/3 support in Java servers including Jetty, Netty, and Undertow. We benchmark real-world performance improvements comparing HTTP/1.1, HTTP/2, and HTTP/3 under various network conditions including high latency and packet loss scenarios. Attendees will learn how QUIC's connection migration enables seamless network switching for mobile clients without dropping ongoing requests. The session covers server configuration for HTTP/3 including certificate setup, Alt-Svc header configuration, and fallback strategies for clients that don't support QUIC. We discuss load balancer considerations since QUIC uses UDP instead of TCP and how this affects existing infrastructure. Monitoring and debugging tools for QUIC connections help operations teams troubleshoot connectivity issues. The talk concludes with a migration roadmap for teams planning to adopt HTTP/3.",
                "Lisa Turner", "English", performance);
        createTalk("API Design: REST, GraphQL, or gRPC?",
                "Choosing the right API style has long-term implications for your system's scalability, developer experience, and evolution capabilities. This talk compares REST, GraphQL, and gRPC across multiple dimensions with practical examples and honest assessments of each technology's strengths and weaknesses. We cover performance characteristics including payload size, serialization overhead, and connection multiplexing differences between the three styles. Attendees will learn about developer experience trade-offs including tooling maturity, documentation generation, and client SDK availability for each approach. The session discusses API evolution strategies showing how each style handles versioning, deprecation, and backward compatibility. We examine real-world usage patterns where companies use multiple API styles for different use cases within the same system. Security considerations cover authentication, authorization, and input validation patterns specific to each style. Practical decision frameworks help teams choose the right style based on their specific requirements and constraints.",
                "Samuel Okafor", "English", architecture);
        createTalk("Data Mesh: Decentralized Data Ownership",
                "El data mesh propone tratar los datos como un producto con propiedad descentralizada, un cambio radical respecto al modelo centralizado de data lakes y data warehouses. Esta charla explica los cuatro principios fundamentales del data mesh: propiedad de dominio, datos como producto, plataforma de datos self-service e gobernanza federada. Mostramos cómo implementar estos principios con herramientas como Spring Boot para APIs de datos, Kafka para streaming, y dbt para transformaciones. Los asistentes aprenderán a definir contratos de datos que garantizan calidad y compatibilidad entre dominios. Discutimos los desafíos organizativos incluyendo la resistencia al cambio y cómo estructurar equipos alrededor de dominios de datos. La sesión cubre métricas de calidad de datos y cómo implementar SLAs para productos de datos. Casos de estudio de empresas que adoptaron data mesh muestran tanto los beneficios como los errores comunes que debemos evitar durante la transición.",
                "Valentina Ruiz", "Spanish", data);
        createTalk("Load Testing Spring Boot APIs with Gatling",
                "Performance issues often surface only under realistic production load, making load testing an essential practice for reliable APIs. This session demonstrates how to write realistic load tests for Spring Boot APIs using Gatling, the Scala-based load testing framework with an expressive DSL. We cover scenario design that models real user behavior including think times, session data, and conditional flows. Attendees will learn ramp-up strategies from smoke tests through stress tests to soak tests that reveal different categories of performance problems. The session demonstrates interpreting Gatling's detailed HTML reports to identify bottlenecks in response time percentiles, throughput, and error rates. We cover parameterization techniques for realistic data variation and how to manage test data lifecycle. Integration with CI/CD pipelines enables performance regression detection on every build using assertion-based thresholds. Advanced topics include distributed load generation for high-throughput scenarios and correlation with server-side metrics from Prometheus for root cause analysis.",
                "Ahmed Hassan", "English", testing);
        createTalk("Trunk-Based Development: Making It Work",
                "El desarrollo trunk-based elimina las ramas de larga vida y sus costosos merges, pero requiere disciplina y prácticas de apoyo para funcionar correctamente. Esta charla muestra cómo adoptar trunk-based development de manera gradual en equipos de cualquier tamaño. Cubrimos las técnicas esenciales: feature flags para ocultar trabajo en progreso, pair programming para revisión continua, y CI ultrarrápido que valida cada commit en minutos. Los asistentes aprenderán estrategias para descomponer features grandes en incrementos pequeños y seguros que se pueden integrar al trunk diariamente. Discutimos cómo manejar el trabajo experimental con branch-by-abstraction y cómo configurar el pipeline de CI para detectar problemas antes del merge. La sesión aborda las preocupaciones más comunes de los equipos que consideran esta transición, incluyendo la gestión de releases y la coordinación entre equipos. Presentamos métricas de equipos que adoptaron trunk-based development mostrando mejoras en lead time y frecuencia de despliegue.",
                "Martín Aguilar", "Spanish", devops);
        createTalk("Evaluating LLM Output Quality at Scale",
                "Wie misst man die Qualität von LLM-Ausgaben systematisch, wenn menschliche Bewertung nicht skaliert? Dieser Vortrag stellt Frameworks und Methoden für die automatisierte Evaluierung von KI-Systemen in Produktion vor. Wir behandeln den LLM-as-Judge-Ansatz, bei dem ein stärkeres Modell die Ausgaben eines schwächeren bewertet, einschließlich Kalibrierung und Bias-Erkennung. Die Teilnehmer lernen RAGAS-Metriken für RAG-Systeme kennen: Faithfulness, Answer Relevancy, Context Precision und Context Recall. Der Vortrag zeigt, wie man Evaluierungs-Pipelines mit Spring AI aufbaut, die bei jedem Deployment automatisch Regressionstests gegen einen kuratierten Testdatensatz durchführen. Wir diskutieren die Erstellung von Gold-Standard-Datensätzen und wie man menschliche Bewertungsprotokolle effizient in den Evaluierungsprozess integriert. Außerdem behandeln wir A/B-Testing von Prompt-Varianten und Modellversionen in Produktion. Praxisbeispiele zeigen, wie Teams Qualitätsmetriken nutzen, um kontinuierliche Verbesserungen ihrer KI-Anwendungen zu steuern.",
                "Hannah Richter", "German", ai);
        createTalk("Migrating from Monolith to Microservices — Lessons Learned",
                "Viele Teams unterschätzen die Komplexität einer Microservice-Migration und stehen nach Monaten der Arbeit vor unerwarteten Herausforderungen. Dieser Vortrag teilt Erfahrungen aus drei großen Migrationsprojekten in unterschiedlichen Branchen und zeigt die häufigsten Fehler sowie bewährte Strategien für einen erfolgreichen Übergang. Wir besprechen, wie man die richtigen Service-Grenzen identifiziert, indem man Domain-Driven-Design-Techniken wie Event Storming und Context Mapping einsetzt. Die Teilnehmer lernen, welche Teile des Monolithen zuerst extrahiert werden sollten und welche besser im Monolith bleiben. Der Vortrag behandelt die Datenbank-Dekomposition als größte technische Herausforderung und zeigt Muster wie Database-per-Service und Shared-Database mit klaren Schema-Grenzen. Wir diskutieren organisatorische Aspekte einschließlich Team-Topologien und wie man Conway's Law zu seinem Vorteil nutzt. Abschließend präsentieren wir Metriken, die den Fortschritt der Migration messbar machen.",
                "Claudia Braun", "German", modernization);
        createTalk("CORS, CSP, and Security Headers Deep Dive",
                "Sicherheitsrelevante HTTP-Header sind die erste Verteidigungslinie gegen XSS, Clickjacking und Datenexfiltration, werden aber oft falsch konfiguriert oder ganz vergessen. Dieser Vortrag erklärt die wichtigsten Security-Header im Detail und zeigt die korrekte Konfiguration in Spring Boot. Wir beginnen mit Content Security Policy und demonstrieren, wie man eine CSP schrittweise verschärft, ohne die Anwendung zu brechen. CORS wird mit allen Aspekten behandelt: einfache Requests, Preflight-Requests, Credentials und wie man häufige Fehlkonfigurationen vermeidet. Die Teilnehmer lernen HSTS, X-Content-Type-Options, X-Frame-Options und Referrer-Policy kennen und verstehen die Sicherheitsrisiken, die jeder Header adressiert. Der Vortrag zeigt, wie man Security-Header in Spring Security konfiguriert und wie man automatisierte Tests schreibt, die die korrekte Header-Konfiguration bei jedem Build überprüfen. Außerdem diskutieren wir Reporting-Mechanismen wie CSP-Report-URI und Report-To, die Verstöße in Produktion sichtbar machen.",
                "Stefan Krause", "German", security);
        createTalk("Service Mesh Deep Dive: Istio vs. Linkerd",
                "Service meshes add observability, security, and traffic management to microservices without requiring application code changes, but they come with significant operational complexity. This talk provides a detailed comparison of Istio and Linkerd based on hands-on production experience with both technologies. We cover resource overhead including CPU and memory consumption of sidecar proxies and control plane components. Attendees will learn about operational complexity differences including installation, upgrade procedures, and debugging tools available in each mesh. The session compares security features including mutual TLS implementation, authorization policies, and certificate management approaches. Traffic management capabilities like canary deployments, circuit breaking, and retry policies are demonstrated for both meshes. We also discuss observability features including distributed tracing integration, metrics collection, and service topology visualization. A decision framework helps teams choose the right mesh based on their specific requirements and operational maturity.",
                "Alex Rivera", "English", cloud);
        createTalk("Flyway vs. Liquibase: Database Migration Strategies",
                "Database schema migrations need to be reliable, repeatable, and auditable to maintain data integrity across environments. This talk compares Flyway and Liquibase for Spring Boot projects, helping teams choose the right tool and adopt best practices. We cover the fundamental philosophical differences between the two tools and how they approach migration management. Attendees will learn about SQL-based migrations in Flyway versus XML, YAML, and SQL changesets in Liquibase and when each format is preferable. The session covers rollback strategies including Flyway's undo migrations and Liquibase's built-in rollback support with honest assessments of their reliability. We demonstrate multi-tenant migration patterns for SaaS applications where hundreds of database schemas need to be migrated consistently. Advanced topics include baseline migrations for existing databases, conditional migrations based on database type, and migration testing strategies that catch errors before production deployment. CI/CD integration patterns ensure migrations run safely as part of automated pipelines.",
                "Derek Simmons", "English", data);
        createTalk("State Management Patterns in Modern Web Apps",
                "From Redux to Signals, state management approaches keep evolving, and choosing the wrong pattern can lead to unnecessary complexity or maintainability problems. This talk compares the most popular patterns including global stores, component-local state, reactive signals, and server-driven state. We examine each pattern's strengths and weaknesses with practical examples showing the same feature implemented using different approaches. Attendees will see how frameworks like Vaadin, React, and Angular handle state differently and how these differences affect application architecture. The session covers emerging patterns like the signal-based reactivity adopted by Angular, Solid, and now Vaadin. We discuss state synchronization challenges in real-time applications and how to handle optimistic updates that need to be reconciled with server state. Performance implications of each pattern are demonstrated with profiling data showing rendering overhead and memory consumption. A decision guide helps teams match state management patterns to their application's specific complexity and requirements.",
                "Yuki Takahashi", "English", frontend);
        createTalk("Designing for Failure: Resilience Patterns in Distributed Systems",
                "Los sistemas distribuidos fallan de maneras impredecibles y las aplicaciones deben diseñarse para manejar estas fallas con elegancia. Esta charla cubre los patrones de resiliencia más importantes con implementaciones prácticas usando Resilience4j y Spring Boot. Comenzamos con el circuit breaker pattern que previene llamadas en cascada a servicios que no responden. Exploramos bulkheads que aíslan fallas para que un componente defectuoso no derrumbe todo el sistema. Los asistentes aprenderán a implementar retry con backoff exponencial y jitter para recuperarse de fallas transitorias sin sobrecargar el servicio destino. Cubrimos timeout propagation para evitar que las solicitudes se acumulen durante degradaciones del servicio. La sesión también trata sobre fallback patterns que proporcionan respuestas degradadas pero útiles cuando los servicios principales no están disponibles. Discutimos cómo combinar estos patrones efectivamente y cómo monitorizarlos para detectar problemas antes de que afecten a los usuarios.",
                "Pablo Herrera", "Spanish", architecture);
        createTalk("Profiling Java Applications in Production",
                "Production profiling requires low-overhead tools that don't impact user experience while providing actionable insights into application behavior. This session covers continuous profiling with Java Flight Recorder, async-profiler, and Pyroscope, demonstrating how to identify CPU hotspots, lock contention, and allocation pressure in live systems. We walk through configuring JFR for continuous recording with configurable thresholds that capture interesting events without filling up disk space. Attendees will learn how to read flame graphs to quickly identify the hottest code paths and how to compare profiles between releases to detect performance regressions. The session demonstrates allocation profiling that reveals which code paths create the most garbage collector pressure. We cover lock contention analysis for applications experiencing throughput problems under concurrent load. Advanced topics include profiling native methods, analyzing GC pauses with JFR events, and setting up automated performance regression detection in CI/CD pipelines. Each technique is shown with real examples from production systems.",
                "Takeshi Nakamura", "English", performance);
        createTalk("Automating Database Deployments in CI/CD Pipelines",
                "Database changes are often the riskiest part of a deployment because schema modifications can cause downtime, data loss, or application errors if not handled carefully. This talk covers automating schema migrations with Flyway in CI/CD pipelines, providing teams with confidence to deploy database changes as frequently as application code. We demonstrate zero-downtime migration patterns including expand-and-contract for column renames, online index creation, and backward-compatible schema changes that support rolling deployments. Attendees will learn rollback strategies including compensating migrations and how to test them before they are needed in production. The session covers data migration testing with representative production data subsets that catch type mismatches and constraint violations early. We discuss approval workflows for sensitive migrations and how to integrate database change review into pull request processes. Monitoring database migration execution time and lock acquisition helps prevent long-running migrations from causing service disruptions.",
                "Diana Brooks", "English", devops);
        createTalk("Multimodal AI: Processing Images and Documents with Spring AI",
                "Modern AI goes beyond text processing, and Spring AI provides the tools to build applications that understand images, documents, and mixed media. This session demonstrates practical multimodal use cases including invoice processing that extracts structured data from scanned documents, content moderation that analyzes both text and images, and product catalog enrichment from manufacturer photos. We walk through configuring Spring AI's chat client for multimodal prompts that combine text instructions with image inputs. Attendees will learn about OCR post-processing with LLMs that corrects recognition errors and extracts semantic meaning from raw text output. The session covers document chunking strategies for multi-page PDFs that maintain section context across chunk boundaries. We discuss cost optimization techniques including image resizing, prompt caching, and routing simple tasks to smaller models. Performance benchmarks compare different model providers for multimodal tasks across accuracy, latency, and cost dimensions.",
                "Sophia Bennett", "English", ai);
        createTalk("Adopting Virtual Threads in Existing Applications",
                "Virtual threads promise massive scalability improvements for I/O-bound Java applications, but adopting them in existing codebases requires careful consideration of several compatibility issues. This talk covers the most common pitfalls including thread-local variable accumulation in virtual threads, synchronized block pinning that negates virtual thread benefits, and third-party library compatibility. We demonstrate how to identify problematic code patterns using JFR events that flag pinned virtual threads. Attendees will learn strategies for gradual migration including running virtual threads alongside platform threads during the transition period. The session covers configuring Spring Boot to use virtual threads for request handling, scheduled tasks, and async operations. We discuss performance testing approaches that reveal whether virtual threads actually improve throughput for your specific workload. Advanced topics include structured concurrency with StructuredTaskScope for coordinated parallel operations and scoped values as a thread-local replacement. Real benchmarks from a production migration show where virtual threads delivered dramatic improvements and where they made no difference.",
                "Jason Lee", "English", modernization);
        createTalk("Deploying Spring Boot to AWS ECS with Fargate",
                "AWS ECS with Fargate eliminates the need to manage Kubernetes clusters while still providing container orchestration capabilities suitable for most Spring Boot applications. This session walks through the complete deployment lifecycle from Dockerfile to production monitoring. We cover task definition configuration including CPU and memory sizing, environment variables, and secrets management with AWS Secrets Manager. Attendees will learn about service configuration including load balancer integration with Application Load Balancer, auto-scaling policies based on CPU and memory utilization, and circuit breaker deployment configurations. The session demonstrates CI/CD pipeline setup using AWS CodePipeline with blue-green deployments that enable instant rollback. We discuss networking options including VPC configuration, security groups, and service discovery with Cloud Map for inter-service communication. Monitoring with CloudWatch Container Insights and X-Ray tracing provides end-to-end visibility. Cost optimization strategies including Fargate Spot for non-critical workloads help teams manage their cloud spend.",
                "Michelle Thompson", "English", cloud);
        createTalk("Vector Databases Compared: pgvector, Weaviate, and Milvus",
                "Choosing the right vector database is critical for AI applications, and the landscape has evolved rapidly with each solution offering distinct trade-offs. This talk provides an in-depth comparison of pgvector, Weaviate, and Milvus based on real benchmarks covering indexing speed, query latency, filtering capabilities, and operational complexity. We start with pgvector as the simplest option that extends your existing PostgreSQL database, covering its HNSW and IVFFlat index types and their performance characteristics. Weaviate is examined as a purpose-built vector database with built-in vectorization modules and GraphQL API. Milvus provides the highest performance for large-scale deployments with its distributed architecture. Attendees will learn about hybrid search capabilities that combine vector similarity with traditional filters in each database. The session covers deployment options from embedded single-node setups to distributed clusters. We discuss integration patterns with Spring AI and how to abstract the vector store choice behind a repository interface. Cost and operational considerations help teams make informed decisions.",
                "Nikolai Smirnov", "English", ai);
        createTalk("Clean Architecture: Pragmatic Boundaries",
                "Clean Architecture promises independence from frameworks and databases, but overzealous application creates unnecessary complexity that slows teams down. This talk shows how to apply clean architecture pragmatically, knowing when strict layer separation adds value and when it creates pointless indirection. We examine real-world applications where clean architecture principles were applied at different levels of rigor and compare the maintenance outcomes. Attendees will learn guidelines for deciding which boundaries deserve formal interfaces and dependency inversion and which can safely use direct dependencies. The session covers common anti-patterns like creating mapper classes for every layer crossing and over-abstracting repositories that will never change their implementation. We discuss how Spring Boot's dependency injection naturally supports clean architecture patterns without requiring additional frameworks. Testing strategies show how clean boundaries enable fast unit tests for business logic while integration tests cover the adapters. The talk concludes with a pragmatic architecture template that teams can adapt to their specific context.",
                "Samantha Reed", "English", architecture);
        createTalk("Caching Strategies with Spring Cache and Redis",
                "Effective caching can reduce database load by orders of magnitude, but incorrect caching creates subtle bugs that are difficult to diagnose. This session covers Spring Cache abstraction with Redis as the backing store, providing a comprehensive guide to caching in Spring Boot applications. We start with the cache-aside pattern and demonstrate annotation-based caching with Cacheable, CachePut, and CacheEvict. Attendees will learn cache key design strategies that prevent collisions and ensure efficient memory usage. The session covers TTL-based expiration, size-based eviction, and how to implement custom eviction policies for domain-specific requirements. We discuss advanced patterns including write-through caching that keeps cache and database synchronized, cache warming strategies for application startup, and cache stampede prevention using probabilistic early expiration. Redis-specific topics include serialization format choices, cluster configuration for high availability, and memory optimization with Redis data structures. Monitoring cache hit rates and memory consumption helps teams tune their caching strategy over time.",
                "Mei Ling", "English", data);
        createTalk("Log Management at Scale with OpenTelemetry",
                "Structured logging combined with OpenTelemetry provides powerful observability that helps teams diagnose production issues in minutes rather than hours. This session covers configuring Spring Boot for structured JSON logging that makes log entries machine-parseable while remaining human-readable. We demonstrate correlating logs with distributed traces by propagating trace and span IDs through the logging MDC. Attendees will learn how to ship logs efficiently to backends like Loki and Elasticsearch using the OpenTelemetry Collector as a unified pipeline. The talk covers log level management including dynamic log level changes in production without restarts and strategies for reducing log volume without losing important information. We discuss structured logging best practices including consistent field naming, sensitive data redaction, and contextual enrichment with request metadata. Advanced topics include log-based alerting that complements metric-based alerting and how to build effective log dashboards in Grafana. Cost management strategies help teams control storage expenses as log volumes grow with their infrastructure.",
                "Sanjay Patel", "English", devops);
        createTalk("Connection Pooling Done Right with HikariCP",
                "Connection pool misconfiguration causes both performance issues and production outages, yet most teams use default settings without understanding their implications. This talk provides a deep understanding of HikariCP internals including how connections are managed, how the pool handles contention, and what happens during database failover. We cover the optimal pool sizing formula that considers both database and application constraints, explaining why more connections often means worse performance. Attendees will learn how to monitor pool health using HikariCP's built-in metrics and Micrometer integration. The session demonstrates common failure scenarios including connection leaks from unclosed resources, pool exhaustion under load, and stale connections after network disruptions. We discuss configuration parameters including maximum pool size, minimum idle connections, connection timeout, and validation query strategies. Advanced topics include multi-datasource pooling for applications that connect to multiple databases and read-write splitting configurations. Troubleshooting guides with specific symptoms and solutions help teams quickly resolve pool-related production issues.",
                "Julia Andersen", "English", performance);
        createTalk("Animation and Motion Design in Web Applications",
                "Subtle animations can dramatically improve user experience by providing visual feedback, guiding attention, and creating a sense of continuity between interface states. This talk covers the Web Animations API, CSS transitions, and the new View Transitions API, demonstrating how to add meaningful motion to Vaadin and React applications without sacrificing performance. We start with animation principles borrowed from motion design including timing, easing, and the importance of animation purpose. Attendees will learn how to implement micro-interactions for button clicks, form validation, and loading states that make applications feel responsive. The session covers page transitions using the View Transitions API that creates smooth crossfades between routes. We demonstrate skeleton screens and staggered list animations that improve perceived performance during data loading. Performance considerations include using CSS transforms instead of layout-triggering properties, will-change optimization, and how to respect user preferences for reduced motion. Each animation pattern is shown with code examples and live demos.",
                "Marie Laurent", "English", frontend);
        createTalk("From JSP to Vaadin: Modernizing Legacy Web UIs",
                "Many enterprise applications still run JSP-based frontends that are difficult to maintain, test, and extend with modern UI features. This session provides a practical migration path from JSP to Vaadin that preserves existing business logic while gaining a modern component-based UI architecture. We start with an assessment framework that helps teams evaluate which JSP pages to migrate first based on maintenance burden and user impact. Attendees will learn incremental migration strategies that allow both technologies to coexist during the transition period using iframe embedding and shared session state. The talk covers mapping common JSP patterns to Vaadin equivalents including form handling with data binding, table rendering with Vaadin Grid, and navigation with the Vaadin Router. We discuss how to preserve URL structures for bookmarks and SEO during migration. Testing strategies ensure feature parity between old and new implementations. The session includes effort estimation guidelines based on real migration projects that help teams plan timelines and resource allocation.",
                "Marta Kowalczyk", "English", modernization);
        createTalk("Post-Quantum Cryptography for Java Applications",
                "Quantum computers threaten current cryptographic standards including RSA and elliptic curve algorithms, and the migration to post-quantum algorithms must begin now to protect data with long-term confidentiality requirements. This session covers the NIST-standardized post-quantum algorithms CRYSTALS-Kyber for key encapsulation and CRYSTALS-Dilithium for digital signatures. We demonstrate their Java implementations via Bouncy Castle and discuss performance characteristics compared to classical algorithms. Attendees will learn about the harvest-now-decrypt-later threat model that makes migration urgent for data that needs to remain confidential for decades. The talk covers hybrid approaches that combine classical and post-quantum algorithms during the transition period to maintain security even if one algorithm is broken. We discuss TLS 1.3 integration with post-quantum key exchange and how Java security providers support algorithm negotiation. Migration planning strategies help organizations inventory their cryptographic dependencies and prioritize systems for upgrade. The session concludes with a timeline of expected quantum computing milestones and regulatory requirements.",
                "Hiroshi Yamamoto", "English", security);
        createTalk("Infrastructure as Code with Pulumi and Java",
                "Terraform uses HCL, a domain-specific language that Java developers must learn separately, but Pulumi lets you define infrastructure in real programming languages including Java. This talk shows how Java developers can use Pulumi to provision cloud resources with familiar language constructs, type safety, and IDE support including autocompletion and refactoring. We cover core concepts including resources, stacks, configuration, and secrets management. Attendees will learn how to provision common infrastructure patterns like VPCs, ECS clusters, RDS databases, and S3 buckets using Java classes. The session demonstrates testing infrastructure code with JUnit including unit tests that verify resource properties and integration tests that provision real resources. We compare Pulumi with Terraform across dimensions including state management, module ecosystem, drift detection, and team collaboration workflows. Advanced topics include custom resource providers, dynamic providers for API-driven resources, and policy-as-code with Pulumi CrossGuard. A migration guide helps teams convert existing Terraform configurations to Pulumi Java.",
                "Tomás Herrera", "English", cloud);
        createTalk("Saga Pattern for Distributed Transactions",
                "Distributed transactions across microservices are notoriously difficult because traditional two-phase commit doesn't scale and introduces tight coupling between services. This session covers the saga pattern with both choreography and orchestration approaches, helping teams choose the right one for their use case. We demonstrate choreography-based sagas where services react to events published by other services, discussing the implicit coupling and debugging challenges this creates. Orchestration-based sagas use a central coordinator that explicitly manages the transaction flow, and we show how to implement one using Spring State Machine. Attendees will learn how to design compensating transactions that reliably undo previous steps when a saga fails. The session covers idempotency strategies that handle duplicate messages and network retries without corrupting data. We discuss failure recovery including how to handle partial failures, timeout detection, and manual intervention for sagas that cannot complete automatically. Monitoring and observability patterns help teams track saga progress and diagnose stuck or failed transactions in production.",
                "Andrei Popescu", "English", architecture);
        createTalk("Approval Testing for Complex Output",
                "When output is complex — HTML pages, JSON API responses, PDF reports, or generated images — assertion-based tests become unwieldy and fragile. Approval testing captures output and compares it against previously approved baselines, making it easy to detect unintended changes while accommodating intentional ones. This talk shows how to apply approval testing in Java using the ApprovalTests library with practical examples from real projects. We cover setting up approval tests for different output types including serialized objects, rendered HTML, and file-based output. Attendees will learn strategies for managing approval files in version control and how to handle non-deterministic output like timestamps and random identifiers. The session demonstrates combination approvals that test multiple input combinations in a single test method. We discuss integration with JUnit 5 and how to set up approval workflows in CI/CD where failing approvals block the build but provide clear diffs for review. Advanced topics include custom reporters that display differences in domain-specific formats and strategies for reviewing large-scale changes efficiently.",
                "Monica Nguyen", "English", testing);
        createTalk("Building Real-Time Data Pipelines with Spring Cloud Data Flow",
                "Spring Cloud Data Flow orchestrates data processing pipelines for both batch and streaming workloads, providing a unified platform for building, deploying, and monitoring data flows. This talk demonstrates building ETL pipelines that extract data from source systems, transform it according to business rules, and load it into target databases or analytics platforms. We cover real-time analytics pipelines using Spring Cloud Stream that process events from Kafka topics with sub-second latency. Attendees will learn how to design modular pipeline components using the Spring Cloud Stream programming model that can be composed into different topologies. The session demonstrates the Data Flow dashboard for deploying and monitoring pipelines including metrics, health checks, and log aggregation. We discuss scaling strategies including partition-based parallelism and auto-scaling based on message backlog. Advanced topics include error handling patterns, dead letter queues, and how to implement exactly-once processing semantics. Cost optimization strategies help teams manage infrastructure spend for always-on streaming pipelines.",
                "Gregory Barnes", "English", data);
        createTalk("Incident Management: From Alert to Resolution",
                "Gute Incident-Management-Prozesse reduzieren die Ausfallzeit drastisch und verbessern die langfristige Systemresilienz durch strukturiertes Lernen aus Vorfällen. Dieser Vortrag behandelt den gesamten Incident-Lifecycle von der ersten Alarmierung bis zum Post-Mortem. Wir besprechen die Gestaltung effektiver On-Call-Rotationen, die Burnout vermeiden und gleichzeitig schnelle Reaktionszeiten sicherstellen. Die Teilnehmer lernen, wie man Eskalationspfade definiert, die klar regeln, wann und wie weitere Personen hinzugezogen werden. Der Vortrag zeigt, wie man Runbooks erstellt, die auch unter Stress zuverlässig funktionieren und schrittweise durch Diagnose und Behebung häufiger Probleme führen. Wir diskutieren blameless Post-Mortem-Kultur und wie man aus Vorfällen systematisch lernt, ohne Schuldzuweisungen. Tools wie PagerDuty, OpsGenie und Grafana OnCall werden verglichen. Außerdem behandeln wir Severity-Level-Definitionen und SLA-Management. Praxisbeispiele aus verschiedenen Unternehmen zeigen, wie gutes Incident Management die Mean Time to Recovery signifikant verkürzt.",
                "Martin Wolf", "German", devops);
        createTalk("Prompt Engineering Patterns for Java Developers",
                "Prompt engineering is a skill every developer building AI-powered applications needs to master, and this session provides a comprehensive toolkit of proven patterns. We cover chain-of-thought prompting that dramatically improves reasoning quality for complex tasks by instructing the model to show its work step by step. Few-shot learning with carefully crafted examples teaches the model your specific output format and quality expectations. Attendees will learn how to write effective system prompts that establish consistent behavior across conversations. The session demonstrates output structuring techniques using JSON schema instructions and format enforcement that produce reliable, parseable responses. We discuss prompt templates in Spring AI including variable substitution and conditional sections that adapt prompts to different contexts. Advanced topics include self-consistency checking where multiple prompt variations validate each other's outputs and meta-prompting where one LLM call generates optimized prompts for another. Each pattern is demonstrated with Java code using Spring AI and includes before-and-after quality comparisons.",
                "Nathan Brooks", "English", ai);
        createTalk("Identity Federation with SAML and OpenID Connect",
                "Las empresas modernas necesitan integrar múltiples proveedores de identidad para empleados, socios y clientes, y la federación de identidades es la clave para hacerlo de manera segura y escalable. Esta charla compara en profundidad SAML 2.0 y OpenID Connect, explicando cuándo cada protocolo es más apropiado. Mostramos cómo configurar ambos protocolos en Spring Security con ejemplos completos de configuración para proveedores como Azure AD, Okta y Keycloak. Los asistentes aprenderán sobre el flujo de autenticación completo incluyendo intercambio de metadatos, gestión de sesiones y single logout. Discutimos patrones para entornos multi-tenant donde diferentes organizaciones usan diferentes proveedores de identidad. La sesión cubre la gestión de atributos y claims incluyendo mapeo de roles y grupos desde el proveedor de identidad a los roles de la aplicación. También abordamos la migración gradual de autenticación local a federada sin interrumpir a los usuarios existentes. Consideraciones de seguridad como validación de tokens y protección contra ataques de replay completan la presentación.",
                "Andrea Vega", "Spanish", security);
        createTalk("Edge Computing with Spring Boot",
                "Not all workloads belong in centralized data centers, and edge computing brings processing closer to data sources for lower latency and reduced bandwidth costs. This session explores deploying Spring Boot applications to edge locations for real-time processing of IoT sensor data, video analytics, and local decision-making. We cover architecture patterns including fog computing layers that aggregate and pre-process data before forwarding to cloud services. Attendees will learn about Spring Boot's suitability for resource-constrained edge devices including memory optimization and fast startup configurations. The session covers data synchronization challenges between edge and cloud including conflict resolution strategies and eventual consistency patterns. We discuss offline-capable designs that continue functioning when cloud connectivity is interrupted, queuing data for later synchronization. Security considerations for edge deployments include certificate management, secure boot, and protecting against physical device tampering. Monitoring distributed edge deployments with centralized observability platforms and handling firmware updates across device fleets round out the operational perspective.",
                "Patricia Wu", "English", cloud);
        createTalk("Evolutionary Architecture with Fitness Functions",
                "Architecture decisions made today may not be right tomorrow as requirements change, technology evolves, and teams grow. This talk introduces evolutionary architecture, an approach that embraces change by making architectural characteristics measurable and continuously monitored. Fitness functions are automated tests that verify architectural properties like coupling between modules, response time percentiles, security compliance, and deployment frequency. We demonstrate how to implement fitness functions using ArchUnit for structural rules, JMeter for performance budgets, and custom metrics for domain-specific architectural qualities. Attendees will learn how to integrate fitness functions into CI/CD pipelines as architectural governance gates that prevent unintended degradation. The session covers the tension between innovation speed and architectural integrity and how fitness functions provide guardrails without bureaucratic review processes. We discuss incremental architecture where the system evolves through guided, reversible changes rather than big-bang redesigns. Real examples from organizations that adopted evolutionary architecture show how it improved their ability to adapt to changing business requirements.",
                "Karen Liu", "English", architecture);
        createTalk("NoSQL in Practice: When and How to Use MongoDB with Spring",
                "Nicht jede Anwendung braucht ein relationales Datenmodell, und MongoDB bietet Flexibilität für Anwendungsfälle mit variablen Schemas, hierarchischen Dokumenten und hohen Schreiblasten. Dieser Vortrag zeigt, wann MongoDB die richtige Wahl ist und wann ein relationales Modell besser passt. Wir behandeln Spring Data MongoDB im Detail einschließlich Repository-Abstraktion, MongoTemplate für komplexe Queries und die Aggregation Pipeline für analytische Abfragen. Die Teilnehmer lernen Best Practices für Schema-Design in MongoDB: Embedding versus Referencing, Denormalisierung für Leseperformance und Schema-Versionierung für die Weiterentwicklung der Datenstrukturen. Der Vortrag zeigt häufige Fallstricke wie unbegrenztes Array-Wachstum, fehlende Indizes auf häufig abgefragten Feldern und Transaktions-Handling in verteilten Deployments. Wir diskutieren die Integration mit Spring Boot einschließlich Konfiguration, Connection-Pooling und Health-Checks. Migrations-Strategien mit Mongock helfen Teams, Schema-Änderungen sicher und wiederholbar durchzuführen. Performance-Benchmarks vergleichen MongoDB mit PostgreSQL für verschiedene Anwendungsszenarien.",
                "Sabine Keller", "German", data);
        createTalk("TDD in the Age of AI: Still Relevant?",
                "With AI generating both production code and tests, many developers question whether Test-Driven Development is still a valuable practice. This talk argues that TDD is more relevant than ever, but the practice needs to evolve for AI-augmented workflows. We examine how TDD's core benefits — design feedback, specification clarity, and regression safety — become even more important when AI generates code that developers need to verify and maintain. Attendees will learn how to use TDD as a specification language when working with AI coding assistants, writing tests first to precisely communicate intent. The session demonstrates workflows where TDD guides AI-generated code toward better designs by constraining the solution space through test requirements. We discuss how to maintain test quality when AI suggests test implementations that pass but don't actually verify meaningful behavior. Advanced topics include mutation testing as a meta-check on AI-generated tests and property-based testing for specifying invariants that AI-generated code must maintain. Real team experiences show how TDD practices adapted for AI-augmented development produce more reliable and maintainable software.",
                "Chris Andersen", "English", testing);
        createTalk("Upgrading to Jakarta EE 11",
                "La migración de Java EE a Jakarta EE implica más que un simple cambio de namespace, y Jakarta EE 11 trae cambios significativos que afectan la arquitectura de las aplicaciones empresariales. Esta charla cubre las novedades más importantes de Jakarta EE 11 incluyendo las actualizaciones en CDI, JAX-RS y JPA. Los asistentes aprenderán estrategias probadas de migración para aplicaciones existentes, desde la migración automática con herramientas como Eclipse Transformer hasta la migración manual controlada. Discutimos las incompatibilidades más frecuentes entre javax y jakarta y cómo resolverlas incluyendo dependencias transitivas que todavía usan el namespace antiguo. La sesión cubre las nuevas APIs introducidas en Jakarta EE 11 que simplifican el desarrollo como Jakarta Data para acceso a datos y mejoras en Jakarta REST. También abordamos la compatibilidad con servidores de aplicaciones incluyendo las últimas versiones de Payara, WildFly y Open Liberty. Estrategias de testing garantizan que la migración no introduzca regresiones. Finalmente presentamos un plan de migración con fases y checkpoints que los equipos pueden adaptar a sus proyectos.",
                "Fernando López", "Spanish", modernization);
        createTalk("Internationalization Beyond Translation",
                "L'internationalisation ne se limite pas à la traduction de textes et beaucoup d'applications échouent sur les aspects techniques du support multilingue. Cette présentation couvre le formatage correct des dates, nombres et devises selon les conventions locales en utilisant les API Java ICU et les standards CLDR. Nous explorons la gestion des fuseaux horaires avec l'API java.time et les pièges courants comme l'heure d'été et les changements de fuseau historiques. La bidirectionnalité du texte pour les langues arabes et hébraïques est traitée en détail, y compris le mélange de texte LTR et RTL dans la même interface. Les participants apprendront les stratégies de chargement des ressources linguistiques à la demande pour éviter de charger toutes les traductions au démarrage. Nous discutons de la pluralisation correcte qui va au-delà du simple singulier et pluriel pour des langues comme le polonais ou l'arabe qui ont des règles complexes. La session couvre également la pseudo-localisation pour tester l'interface sans traductions réelles et les outils d'automatisation qui détectent les chaînes non internationalisées dans le code source.",
                "Pierre Dubois", "French", frontend);
        createTalk("Cost Optimization for AI-Powered Applications",
                "Die Kosten für AI-APIs können schnell explodieren, wenn Teams nicht von Anfang an Kostenoptimierung in ihre Architektur einplanen. Dieser Vortrag zeigt bewährte Strategien zur Kostenreduktion für produktive AI-Anwendungen. Wir beginnen mit intelligentem Caching: semantisches Caching, das ähnliche Anfragen erkennt und gespeicherte Antworten wiederverwendet, kann die API-Kosten um bis zu siebzig Prozent senken. Prompt-Komprimierung reduziert Token-Verbrauch ohne nennenswerten Qualitätsverlust durch Entfernung redundanter Instruktionen und Beispiele. Die Teilnehmer lernen Modell-Routing-Strategien kennen, die einfache Anfragen automatisch an günstigere und schnellere Modelle weiterleiten und nur komplexe Aufgaben an leistungsfähigere Modelle senden. Batch-Verarbeitung aggregiert mehrere Anfragen, um API-Overhead und Latenz zu minimieren. Wir diskutieren den strategischen Einsatz von Open-Source-Modellen über Ollama für Aufgaben, die keine Frontier-Modelle erfordern. Der Vortrag enthält ein Cost-Dashboard-Template für Grafana, das API-Kosten pro Feature und pro Nutzer transparent macht.",
                "Felix Neumann", "German", ai);
        createTalk("Securing Containers: From Build to Runtime",
                "Container security spans the entire lifecycle from building minimal images through secure registry management to runtime threat detection in production. This talk covers a defense-in-depth approach that addresses security at every stage. We start with image building best practices including multi-stage builds, distroless base images that minimize the attack surface, and reproducible builds that ensure image integrity. Attendees will learn how to integrate vulnerability scanning with Trivy into CI/CD pipelines with configurable severity thresholds that block deployments when critical vulnerabilities are found. The session covers Kubernetes security contexts including seccomp profiles, AppArmor policies, and pod security standards that limit container capabilities. We demonstrate runtime threat detection with Falco that monitors system calls and alerts on suspicious behavior like unexpected process execution or file access. Container networking security including network policies, service mesh encryption, and egress filtering prevents lateral movement and data exfiltration. Secrets management patterns ensure sensitive data never appears in container images or environment variables.",
                "Chris Morgan", "English", security);
        createTalk("Observability in Kubernetes: Logs, Metrics, and Traces",
                "La observabilidad es esencial para operar aplicaciones en Kubernetes de manera confiable, pero implementar los tres pilares — logs, métricas y trazas — de forma coherente requiere una estrategia bien planificada. Esta charla cubre la implementación completa de observabilidad para aplicaciones Spring Boot en Kubernetes. Comenzamos con logging estructurado en formato JSON utilizando Logback y cómo recopilar logs de todos los pods con Fluentd o Vector. Los asistentes aprenderán a instrumentar aplicaciones con Micrometer para exponer métricas en formato Prometheus y a configurar dashboards en Grafana que muestren tanto métricas de infraestructura como métricas de negocio. Cubrimos trazas distribuidas con OpenTelemetry incluyendo propagación automática de contexto entre servicios, sampling adaptativo para controlar el volumen de datos y la correlación entre trazas, métricas y logs. Discutimos alertas efectivas que minimizan falsos positivos usando multi-window multi-burn-rate SLO alerting. La sesión también aborda la gestión del volumen de datos de observabilidad y estrategias de retención que equilibran visibilidad y costo.",
                "Roberto Sánchez", "Spanish", cloud);
        createTalk("Building a Chatbot with Spring AI and Vaadin",
                "Chatbots are the most common AI interface pattern and building a production-quality one requires more than just calling an LLM API. This hands-on session walks through building a complete chatbot using Spring AI for the backend and Vaadin for the UI with streaming token-by-token response display. We cover conversation memory management including sliding window, token-based truncation, and summary-based compression strategies that maintain context within token limits. Attendees will learn how to implement context management that grounds responses in relevant documents using RAG patterns. The session demonstrates building a responsive chat UI with Vaadin that handles streaming responses, typing indicators, markdown rendering, and code syntax highlighting. We cover error handling for API timeouts, rate limits, and content filter blocks that provide graceful degradation rather than cryptic errors. Advanced topics include multi-turn tool calling where the chatbot can query databases and call APIs on behalf of the user. Security considerations cover input sanitization, prompt injection prevention, and output filtering for sensitive information.",
                "Elena Volkov", "English", ai);
        createTalk("Chaos Engineering for Java Applications",
                "Chaos engineering proactively tests system resilience by injecting controlled failures into running systems rather than waiting for production incidents to reveal weaknesses. This session demonstrates how to use Chaos Monkey for Spring Boot to randomly disable beans, add latency to service calls, and throw exceptions in controller methods during integration testing. We cover LitmusChaos for Kubernetes-level chaos including pod termination, network partitioning, and resource pressure experiments. Attendees will learn how to design chaos experiments using the scientific method: form a hypothesis about system behavior, define steady-state metrics, inject failures, and compare results against expectations. The session covers blast radius management that limits the impact of experiments to prevent them from becoming actual incidents. We discuss organizational aspects including building management support for chaos engineering and starting with game days before moving to automated continuous chaos. Advanced topics include chaos testing for data consistency across distributed systems and how to combine chaos engineering with observability to build comprehensive system understanding.",
                "Tanya Ivanova", "English", testing);
        createTalk("Incremental Migration from REST to GraphQL",
                "Replacing REST with GraphQL does not have to be a big-bang migration that risks breaking existing clients and overwhelming the development team. This talk demonstrates how to run both REST and GraphQL APIs side by side, gradually migrating endpoints while maintaining full backward compatibility for existing consumers. We start with identifying which REST endpoints benefit most from GraphQL's flexible querying capabilities, typically those suffering from over-fetching or requiring multiple sequential calls. Attendees will learn how to implement a GraphQL schema that mirrors existing REST resources and how to share service layer code between both API styles. The session covers the Apollo Federation approach for organizations with multiple teams and how Spring for GraphQL supports schema stitching. We discuss client migration strategies including providing GraphQL client libraries and developer documentation that eases the transition. Performance monitoring that compares REST and GraphQL endpoint efficiency helps justify the migration effort. The talk also covers common GraphQL pitfalls like the N+1 query problem and how DataLoader prevents it.",
                "Jessica Harper", "English", modernization);
        createTalk("Building Dashboard UIs with Vaadin Charts and Grid",
                "Dashboards are the most requested UI pattern in enterprise applications, combining data visualization, tabular data, and interactive filters into cohesive views. This hands-on session demonstrates how to build interactive, data-rich dashboards using Vaadin Grid, Charts, and Board components with real-time data updates via server push. We cover Grid configuration including lazy loading for large datasets, inline editing, column reordering, and export functionality. Attendees will learn how to create responsive chart configurations using Vaadin Charts for line charts, bar charts, pie charts, and specialized types like heatmaps and treemaps. The session demonstrates the Board layout component for arranging dashboard widgets in a responsive grid that adapts to different screen sizes. We cover real-time updates using server push that refresh chart and grid data without page reloads. Interactive filtering with cross-widget coordination ensures that selecting a data point in one chart filters data displayed in other components. Performance optimization strategies for dashboards with large datasets include pre-aggregation, virtual scrolling, and partial updates.",
                "Katarina Novak", "English", frontend);
        createTalk("AI-Powered Data Extraction from Unstructured Documents",
                "Enterprises sit on mountains of unstructured data in PDFs, emails, scanned documents, and handwritten notes that contain valuable information locked away from automated processing. This talk demonstrates how to build extraction pipelines using LLMs and Spring AI that convert unstructured content into structured, queryable data. We cover document ingestion including PDF parsing with Apache PDFBox, OCR with Tesseract for scanned documents, and email parsing for extracting attachments and metadata. Attendees will learn how to design extraction prompts that reliably extract specific data fields like dates, amounts, names, and addresses from varied document formats. The session demonstrates validation pipelines that cross-check extracted data against business rules and flag low-confidence extractions for human review. We discuss handling multi-page documents that require context spanning across pages and tables that need structural understanding. Performance optimization through batching, caching, and model selection based on document complexity reduces processing costs. Real-world metrics from an invoice processing system show extraction accuracy rates and processing throughput across different document types.",
                "Robert Chang", "English", ai);
        createTalk("The Future of CSS: Nesting, Layers, and Scoping",
                "CSS hat in den letzten Jahren enorme Fortschritte gemacht und bietet nun Features, die früher nur mit Präprozessoren wie Sass möglich waren. Dieser Vortrag behandelt die wichtigsten neuen CSS-Spezifikationen und zeigt, wie sie das Styling komplexer Webanwendungen grundlegend vereinfachen. Natives CSS-Nesting ermöglicht es, verschachtelte Selektoren direkt in CSS zu schreiben, was die Lesbarkeit verbessert und die Abhängigkeit von Build-Tools reduziert. Cascade Layers bieten explizite Kontrolle über die Spezifitäts-Reihenfolge und lösen damit eines der hartnäckigsten Probleme in großen CSS-Codebasen. CSS Scoping begrenzt Styles auf bestimmte DOM-Teilbäume und verhindert unbeabsichtigte Seiteneffekte zwischen Komponenten. Die Teilnehmer lernen, wie sie diese Features zusammen einsetzen können, um wartbare und skalierbare Stylesheets zu erstellen. Wir zeigen die Integration mit Vaadin-Theming und Web Components einschließlich Shadow DOM und CSS Custom Properties. Außerdem diskutieren wir die Browser-Kompatibilität und Polyfill-Strategien für Teams, die ältere Browser unterstützen müssen.",
                "Florian Hartmann", "German", frontend);
    }

    private Category createCategory(String name) {
        Category category = new Category();
        category.setName(name);
        return categoryRepository.save(category);
    }

    private void createTalk(String title, String description, String speaker, String language, Category category) {
        Talk talk = new Talk();
        talk.setTitle(title);
        talk.setDescription(description);
        talk.setSpeaker(speaker);
        talk.setLanguage(language);
        talk.setCategory(category);
        talkRepository.save(talk);
    }
}
